// src/lib/quellen/fakten.js – Fakten-Suche /quellen (Welle 4, Paket FAKTEN)
//
// Stufe 1 des Fakten-Assistenten (Masterplan: GEO/KI-Suche – Faktenregister → /quellen),
// ausdrücklich OHNE KI: reine Aufbereitung des Faktenregisters (src/lib/fakten) für die
// durchsuchbare Seite /quellen, die Export-Routen /quellen/fakten.csv und /quellen/fakten.json
// und die Tests. Keine eigene Fachlogik, keine neuen Werte – jede Zahl kommt unverändert aus
// dem Register, mit Quelle, Abrufdatum, Prüfer, Klasse und Gültigkeit.
//
//  - quellenEintraege(): ein Eintrag je Fakt (id + land), Entwürfe ausgeschlossen
//    (schema.js: „entwurf = nicht freigegeben, wird nie verwendet“). Mehrere zeitliche
//    Versionen desselben Fakts (gueltigAb) werden zu EINEM Eintrag mit Versionsliste.
//  - Abgelaufene Werte: istAbgelaufen()/anzeigeStatus() aus schema.js (dieselbe Logik wie
//    pruefen.js, Masterplan H7: nie als aktuell zeigen) → Feld `abgelaufen` + HINWEIS_ABGELAUFEN.
//  - Anker: stabile URL je Fakt (#fakt-<land>-<id>) für Zitate durch KI-Suchmaschinen und Presse.
//  - Export: CSV und JSON unter CC BY 4.0 (Lizenzgeber ÖkoInvest GmbH für die Zusammenstellung;
//    jede Zeile nennt ihre Primärquelle).
//
// Reine Funktionen ohne I/O und ohne React – nutzbar in Server-Seite, Client-Baustein,
// Route-Handlern und node:test.

import { HINWEIS_ABGELAUFEN, KLASSEN, alleFakten, anzeigeStatus, istAbgelaufen, isoHeute, pruefeFakten } from "@/lib/fakten";

/** Lizenz der Zusammenstellung (Export): Namensnennung „ÖkoInvest GmbH – Faktenregister“. */
export const LIZENZ = Object.freeze({
  name: "CC BY 4.0",
  url: "https://creativecommons.org/licenses/by/4.0/",
  namensnennung: "ÖkoInvest GmbH – Faktenregister, www.oekoinvest.com/quellen",
});

// Such- und Themen-Helfer (auch für den Client-Baustein, ohne Register-Import): ./filter.js
export { THEMEN, filtere, themaName, themaVon, trifft } from "./filter.js";
import { themaVon } from "./filter.js";

/**
 * Stabiler Anker eines Fakts: #fakt-<land klein>-<id> (id unverändert, Punkte erlaubt).
 * NIE ändern – die Anker sind zitierfähige URLs (#fakt-de-pacht.freiflaecheProHa).
 */
export const ankerFuer = (id, land) => `fakt-${String(land || "").toLowerCase()}-${id}`;

const zahl = (n) => (Number.isFinite(n) ? n.toLocaleString("de-DE", { maximumFractionDigits: 4 }) : String(n));

/**
 * Wert eines Fakts als Text (deutsch, wie im Register – auch in der englischen Oberfläche):
 * Zahlen mit deutschem Tausenderpunkt, Spannen { min, mittel?, max } als „min bis max“,
 * Wahrheitswerte als ja/nein, Tabellen (Arrays) und sonstige Objekte als kompaktes JSON.
 */
export function wertText(wert) {
  if (wert === null || wert === undefined) return "– (Wert offen)";
  if (typeof wert === "number") return zahl(wert);
  if (typeof wert === "boolean") return wert ? "ja" : "nein";
  if (typeof wert === "string") return wert;
  if (Array.isArray(wert)) return `Tabelle mit ${wert.length} Einträgen`;
  if (typeof wert === "object") {
    const { min, mittel, max } = wert;
    if (Number.isFinite(min) && Number.isFinite(max)) {
      return `${zahl(min)} bis ${zahl(max)}${Number.isFinite(mittel) ? ` (Mittel ${zahl(mittel)})` : ""}`;
    }
    return JSON.stringify(wert);
  }
  return String(wert);
}

/** Versionen eines Fakts: aktuelle = spätestes gueltigAb ≤ Stichtag, sonst die früheste. */
function aktuelleVersion(versionen, tag) {
  const inKraft = versionen.filter((f) => !f.gueltigAb || f.gueltigAb <= tag);
  const sortiert = (inKraft.length ? inKraft : versionen).slice().sort((a, b) => String(a.gueltigAb || "").localeCompare(String(b.gueltigAb || "")));
  return inKraft.length ? sortiert[sortiert.length - 1] : sortiert[0];
}

const alsVersion = (f, heute) => ({
  wert: f.wert ?? null,
  wertText: wertText(f.wert),
  gueltigAb: f.gueltigAb ?? null,
  gueltigBis: f.gueltigBis ?? null,
  status: anzeigeStatus(f, heute),
  abruf: f.abruf,
});

/**
 * Einträge der Fakten-Suche: ein Eintrag je Fakt (id + land), ohne Entwürfe,
 * sortiert nach Thema, id, Land. Nur einfache Daten (JSON-fähig) – die Server-Seite
 * reicht das Ergebnis unverändert an den Client-Baustein weiter.
 *
 * @param {{ heute?: Date|string, liste?: object[] }} [optionen] liste = Fakten (Standard: alleFakten())
 */
export function quellenEintraege({ heute = new Date(), liste = alleFakten() } = {}) {
  const tag = isoHeute(heute);
  const gruppen = new Map();
  for (const f of liste) {
    if (!f || f.status === "entwurf") continue;
    const k = `${f.id}|${f.land}`;
    if (!gruppen.has(k)) gruppen.set(k, []);
    gruppen.get(k).push(f);
  }
  const eintraege = [];
  for (const versionen of gruppen.values()) {
    const f = aktuelleVersion(versionen, tag);
    const abgelaufen = istAbgelaufen(f, tag);
    const thema = themaVon(f.id);
    eintraege.push({
      anker: ankerFuer(f.id, f.land),
      id: f.id,
      land: f.land,
      thema,
      klasse: f.klasse,
      klasseText: KLASSEN[f.klasse] || f.klasse,
      status: anzeigeStatus(f, tag),
      abgelaufen,
      hinweis: abgelaufen ? HINWEIS_ABGELAUFEN : null,
      wert: f.wert ?? null,
      wertText: wertText(f.wert),
      einheit: f.einheit,
      quelleTitel: f.quelle?.titel || "",
      quelleUrl: f.quelle?.url || null,
      quelleArt: f.quelle?.art || (f.quelle?.url ? "primaer" : "eigen"),
      abruf: f.abruf,
      gueltigAb: f.gueltigAb ?? null,
      gueltigBis: f.gueltigBis ?? null,
      pruefer: f.pruefer,
      notiz: f.notiz || "",
      herkunft: f.herkunft || "",
      weitereVersionen: versionen
        .filter((v) => v !== f)
        .sort((a, b) => String(a.gueltigAb || "").localeCompare(String(b.gueltigAb || "")))
        .map((v) => alsVersion(v, tag)),
    });
  }
  return eintraege.sort((a, b) => a.thema.localeCompare(b.thema, "de") || a.id.localeCompare(b.id, "de") || a.land.localeCompare(b.land, "de"));
}

/** Zusammenfassung für den Seitenkopf – dieselbe Gate-Logik wie qa/fakten-check.mjs (pruefen.js). */
export function quellenZusammenfassung({ heute = new Date(), liste = alleFakten() } = {}) {
  const ohneEntwuerfe = liste.filter((f) => f?.status !== "entwurf");
  const p = pruefeFakten(ohneEntwuerfe, { heute });
  const abruf = ohneEntwuerfe.map((f) => f?.abruf || "").filter(Boolean).sort();
  return {
    stichtag: p.stichtag,
    urteil: p.urteil,
    fakten: p.zusammenfassung.fakten,
    geprueft: p.zusammenfassung.jeStatus?.geprueft || 0,
    zuPruefen: p.zusammenfassung.zuPruefen,
    abgelaufen: p.zusammenfassung.abgelaufenKlasseA + p.zusammenfassung.abgelaufenKlasseBC,
    jeLand: p.zusammenfassung.jeLand,
    jeKlasse: p.zusammenfassung.jeKlasse,
    letzterAbruf: abruf[abruf.length - 1] || null,
  };
}

// ---------------------------------------------------------------------------
// Export CSV / JSON (CC BY 4.0)
// ---------------------------------------------------------------------------

const CSV_SPALTEN = ["id", "land", "thema", "wert", "einheit", "klasse", "status", "gueltig_ab", "gueltig_bis", "quelle_titel", "quelle_url", "quelle_art", "abruf", "pruefer", "notiz", "anker", "lizenz"];

const csvFeld = (v) => {
  const s = v === null || v === undefined ? "" : String(v);
  return /[";\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

/** CSV-Export (Semikolon, UTF-8, RFC-4180-Anführung): eine Zeile je Eintrag. */
export function alsCsv(eintraege) {
  const zeilen = [CSV_SPALTEN.join(";")];
  for (const e of eintraege) {
    const wert = typeof e.wert === "object" && e.wert !== null ? JSON.stringify(e.wert) : e.wert ?? "";
    zeilen.push(
      [e.id, e.land, e.thema, wert, e.einheit, e.klasse, e.status, e.gueltigAb ?? "", e.gueltigBis ?? "", e.quelleTitel, e.quelleUrl ?? "", e.quelleArt, e.abruf, e.pruefer, e.notiz, `#${e.anker}`, `${LIZENZ.name} (${LIZENZ.url}) – ${LIZENZ.namensnennung}`]
        .map(csvFeld)
        .join(";")
    );
  }
  return `${zeilen.join("\r\n")}\r\n`;
}

/** JSON-Export mit Lizenz- und Stand-Angaben. */
export function alsJsonExport(eintraege, { heute = new Date(), basis = "https://www.oekoinvest.com" } = {}) {
  return {
    name: "ÖkoInvest Faktenregister",
    beschreibung: "Markt- und Rechtswerte zu Photovoltaik in Deutschland, Österreich und der Schweiz – je Wert mit Quelle, Abrufdatum, Prüfstand und Gültigkeit. Entwürfe sind nicht enthalten.",
    stand: isoHeute(heute),
    lizenz: { ...LIZENZ },
    hinweis: "Orientierungswerte, kein Angebot und keine Rechts- oder Anlageberatung. Maßgeblich ist die je Eintrag verlinkte Quelle in ihrer aktuellen Fassung. Status „Prüfung ausstehend“ heißt: noch nicht am Original nachgeprüft.",
    seite: `${basis}/quellen`,
    anzahl: eintraege.length,
    fakten: eintraege.map((e) => ({ ...e, url: `${basis}/quellen#${e.anker}` })),
  };
}

/** Dataset-Schema (JSON-LD) für /quellen – Ausgabe über <JsonLd /> (escaped). */
export function datasetSchema({ heute = new Date(), basis = "https://www.oekoinvest.com", anzahl = 0 } = {}) {
  return {
    "@context": "https://schema.org",
    "@type": "Dataset",
    name: "ÖkoInvest Faktenregister – Photovoltaik DACH",
    description: `Durchsuchbares Faktenregister mit ${anzahl} Markt- und Rechtswerten zu Photovoltaik in Deutschland, Österreich und der Schweiz – je Wert mit Primärquelle, Abrufdatum, Prüfstand, Qualitätsklasse und Gültigkeit. Jeder Fakt hat eine stabile Zitier-URL (Anker).`,
    url: `${basis}/quellen`,
    inLanguage: "de",
    dateModified: isoHeute(heute),
    license: LIZENZ.url,
    creditText: LIZENZ.namensnennung,
    isAccessibleForFree: true,
    creator: { "@type": "Organization", name: "ÖkoInvest GmbH", url: basis },
    spatialCoverage: ["Deutschland", "Österreich", "Schweiz"],
    distribution: [
      { "@type": "DataDownload", encodingFormat: "text/csv", contentUrl: `${basis}/quellen/fakten.csv` },
      { "@type": "DataDownload", encodingFormat: "application/json", contentUrl: `${basis}/quellen/fakten.json` },
    ],
  };
}

// src/lib/quellen/filter.js – reine Such- und Themen-Helfer der Fakten-Suche (Welle 4, Paket FAKTEN)
//
// Bewusst OHNE Import des Faktenregisters: Der Client-Baustein (src/components/Quellen/
// FaktenSuche.js) lädt nur diese Datei – die Fakten selbst kommen als Eigenschaft von der
// Server-Seite (quellenEintraege() in ./fakten.js), nicht noch einmal ins Browser-Bündel.

/** Themen = erster Teil der Fakt-id (vor dem Punkt) mit Anzeigenamen (de/en). */
export const THEMEN = Object.freeze({
  freiflaeche: { de: "Freiflächen-PV", en: "Ground-mounted PV" },
  dach: { de: "Dach-PV", en: "Rooftop PV" },
  pacht: { de: "Pacht", en: "Lease" },
  erloese: { de: "Erlöse", en: "Revenues" },
  zuschlag: { de: "Ausschreibungen", en: "Tenders" },
  recht: { de: "Recht", en: "Law" },
  steuer: { de: "Steuern", en: "Taxes" },
  kav: { de: "Konzessionsabgabe", en: "Concession levy" },
  kommune: { de: "Kommunen", en: "Municipalities" },
  region: { de: "Regionen", en: "Regions" },
  termin: { de: "Fristen und Termine", en: "Deadlines" },
  umlage: { de: "Umlagen", en: "Levies" },
  netzentgelt: { de: "Netzentgelte", en: "Network charges" },
  boerse: { de: "Strommarkt", en: "Power market" },
  gewerbestrom: { de: "Gewerbestrom", en: "Commercial power" },
  gebaeudestrom: { de: "Gebäudestrom", en: "Building power" },
  prozess: { de: "Projektprozess", en: "Project process" },
});

/** Thema (erster id-Teil) eines Fakts. */
export const themaVon = (id) => String(id || "").split(".")[0];

/** Anzeigename eines Themas; unbekannte Themen erscheinen unter ihrem Schlüssel. */
export const themaName = (thema, sprache = "de") => THEMEN[thema]?.[sprache === "en" ? "en" : "de"] || thema;

const norm = (s) =>
  String(s || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/ß/g, "ss");

/** Trifft der Suchtext (Wörter UND-verknüpft) auf einen Eintrag? */
export function trifft(eintrag, text) {
  const woerter = norm(text).split(/\s+/).filter(Boolean);
  if (!woerter.length) return true;
  const heuhaufen = norm([eintrag.id, eintrag.land, eintrag.wertText, eintrag.einheit, eintrag.quelleTitel, eintrag.notiz, themaName(eintrag.thema, "de"), themaName(eintrag.thema, "en")].join(" \n "));
  return woerter.every((w) => heuhaufen.includes(w));
}

/**
 * Filter der Fakten-Suche (Seite, Client-Baustein und Tests nutzen dieselbe Funktion).
 * @param {object[]} eintraege  quellenEintraege()
 * @param {{ text?: string, land?: string, thema?: string, klasse?: string, status?: string }} filter
 *   status: "geprueft" | "zu_pruefen" | "abgelaufen" (anzeigeStatus); land "DACH" steht für sich.
 */
export function filtere(eintraege, { text = "", land = "", thema = "", klasse = "", status = "" } = {}) {
  return eintraege.filter(
    (e) =>
      (!land || e.land === land) &&
      (!thema || e.thema === thema) &&
      (!klasse || e.klasse === klasse) &&
      (!status || e.status === status) &&
      trifft(e, text)
  );
}
// /quellen/fakten.csv – CSV-Export des Faktenregisters (Welle 4, Paket FAKTEN)
//
// Dieselben Einträge wie die Seite /quellen (quellenEintraege(), ohne Entwürfe), als CSV
// mit Semikolon und UTF-8 (RFC-4180-Anführung). Lizenz der Zusammenstellung: CC BY 4.0
// (Spalte „lizenz“ und Link-Kopfzeile); die je Zeile genannte Primärquelle behält ihre
// eigenen Bedingungen. Höchstens stündlich neu erzeugt (wie die Seite).

import { LIZENZ, alsCsv, quellenEintraege } from "@/lib/quellen/fakten";

export const revalidate = 3600;

export async function GET() {
  const csv = alsCsv(quellenEintraege({ heute: new Date() }));
  return new Response(`﻿${csv}`, {
    headers: {
      "Content-Type": "text/csv; charset=utf-8",
      "Content-Disposition": 'attachment; filename="oekoinvest-faktenregister.csv"',
      Link: `<${LIZENZ.url}>; rel="license"`,
      "Cache-Control": "public, max-age=0, s-maxage=3600",
    },
  });
}
// /quellen/fakten.json – JSON-Export des Faktenregisters (Welle 4, Paket FAKTEN)
//
// Dieselben Einträge wie die Seite /quellen (quellenEintraege(), ohne Entwürfe), mit
// Lizenz- und Stand-Angaben sowie der zitierfähigen URL je Fakt (#fakt-<land>-<id>).
// Lizenz der Zusammenstellung: CC BY 4.0; die je Eintrag genannte Primärquelle behält
// ihre eigenen Bedingungen. Höchstens stündlich neu erzeugt (wie die Seite).

import { abs } from "@/data/site";
import { LIZENZ, alsJsonExport, quellenEintraege } from "@/lib/quellen/fakten";

export const revalidate = 3600;

export async function GET() {
  const heute = new Date();
  const daten = alsJsonExport(quellenEintraege({ heute }), { heute, basis: abs("") });
  return Response.json(daten, {
    headers: {
      "Content-Disposition": 'attachment; filename="oekoinvest-faktenregister.json"',
      Link: `<${LIZENZ.url}>; rel="license"`,
      "Cache-Control": "public, max-age=0, s-maxage=3600",
    },
  });
}

// quellen/page.js – Fakten-Suche: das Faktenregister als durchsuchbare Seite (Welle 4, Paket FAKTEN)
//
// Stufe 1 des Fakten-Assistenten (Masterplan GEO: Faktenregister → /quellen) – OHNE KI.
// Die Seite macht das komplette Faktenregister (src/lib/fakten) durchsuchbar: Volltext,
// Filter nach Land, Thema, Qualitätsstufe (Klasse A/B/C) und Prüfstand; jede Zahl mit Quelle,
// Abrufdatum und Prüfer, jeder Fakt mit stabiler Anker-URL (#fakt-<land>-<id>) für Zitate.
// Abgelaufene Werte sind sichtbar markiert (schema.js/pruefen.js, Masterplan H7).
// Export: /quellen/fakten.csv und /quellen/fakten.json unter CC BY 4.0.
//
// noindex: 116 von 159 Fakten tragen Status „Prüfung ausstehend“ (zweite Prüfperson E6 fehlt).
// Indexierung erst, wenn alle gezeigten Fakten am Original geprüft sind → Inhaberpunkt.
// Keine Rechenlogik, keine Leads – reine Dokumentations- und Zitierseite.

import { Database, Download, Scale } from "lucide-react";
import Section from "@/components/ui/Section";
import { Eyebrow } from "@/components/ui/SectionHeading";
import Breadcrumbs from "@/components/ui/Breadcrumbs";
import JsonLd from "@/components/JsonLd";
import FaktenSuche from "@/components/Quellen/FaktenSuche";
import { abs } from "@/data/site";
import { pfad } from "@/lib/land";
import { landDerAnfrage, seitenLand, seitenMetadata, spracheDerAnfrage } from "@/lib/land/seite";
import { schreibweiseBaum } from "@/components/Land/SchweizerSchreibweise";
import { LIZENZ, datasetSchema, quellenEintraege, quellenZusammenfassung } from "@/lib/quellen/fakten";
import { datumDe } from "@/lib/fakten";

// Schweiz (/ch, /en/ch): Texte ohne „ß“ (src/components/Land/SchweizerSchreibweise.js)
const chBaum = (el) => schreibweiseBaum(el, landDerAnfrage());

// „Abgelaufen“ wirkt ohne neuen Build: Seite wird höchstens stündlich neu erzeugt.
export const revalidate = 3600;

const PFAD = pfad("/quellen");

const metadata = {
  title: "Fakten und Quellen | ÖkoInvest",
  description: "Das ÖkoInvest-Faktenregister zum Durchsuchen: Markt- und Rechtswerte zu Photovoltaik in Deutschland, Österreich und der Schweiz – jede Zahl mit Quelle, Abrufdatum, Prüfstand und zitierfähigem Link. Export als CSV und JSON (CC BY 4.0).",
  alternates: { canonical: abs(PFAD) },
  // Fachliche Zweitprüfung (E6) ausstehend; viele Fakten tragen „Prüfung ausstehend“ → nicht indexieren
  robots: { index: false, follow: true },
};

const metadataEn = {
  title: "Facts and sources | ÖkoInvest",
  description: "The ÖkoInvest fact register, searchable: market and legal values for photovoltaics in Germany, Austria and Switzerland – every figure with source, retrieval date, review status and a citable link. Export as CSV and JSON (CC BY 4.0).",
};

const TEXTE = {
  de: {
    wissen: "Wissen",
    quellen: "Fakten und Quellen",
    eyebrow: "Wissen · Faktenregister",
    titel: "Fakten und Quellen",
    lead1: "Jede Zahl dieser Website steht in unserem Faktenregister – mit Primärquelle, Abrufdatum, Prüfstand, Qualitätsstufe und Gültigkeit.",
    lead2: "Hier ist das komplette Register durchsuchbar. Jeder Fakt hat einen festen Link zum Zitieren; abgelaufene Werte sind deutlich markiert und erscheinen nie als aktuell.",
    entwurf: "Entwurf · fachliche Zweitprüfung ausstehend",
    zweit: "keine Rechts- oder Anlageberatung",
    stand: (z) => `${z.fakten} Fakten · davon ${z.geprueft} am Original geprüft, ${z.zuPruefen} in Prüfung${z.abgelaufen ? `, ${z.abgelaufen} abgelaufen` : ""} · letzter Abruf ${datumDe(z.letzterAbruf)}`,
    exportTitel: "Export",
    exportText: "Das Register steht als CSV und JSON unter der Lizenz CC BY 4.0 bereit (Namensnennung: „ÖkoInvest GmbH – Faktenregister“). Jede Zeile nennt ihre Primärquelle – deren Bedingungen gelten unabhängig davon weiter.",
    csv: "CSV herunterladen",
    json: "JSON herunterladen",
    fuss: "Die Qualitätsstufen: Klasse A = Recht, Förderung, Abgaben und Fristen; Klasse B = Markt- und Statistikwerte mit externer Quelle; Klasse C = eigene Einschätzungen aus der Projektpraxis (Orientierung, keine Messwerte). „Am Original geprüft“ heißt: Der Wert wurde an der verlinkten Primärquelle nachgelesen; die fachliche Zweitprüfung steht noch aus. Entwürfe zeigt diese Seite nicht. Maßgeblich ist immer die verlinkte Quelle in ihrer aktuellen Fassung.",
    enHinweis: null,
  },
  en: {
    wissen: "Knowledge",
    quellen: "Facts and sources",
    eyebrow: "Knowledge · fact register",
    titel: "Facts and sources",
    lead1: "Every figure on this website lives in our fact register – with primary source, retrieval date, review status, quality level and validity.",
    lead2: "The full register is searchable here. Every fact has a stable link for citations; expired values are clearly marked and never shown as current.",
    entwurf: "Draft · second specialist review pending",
    zweit: "not legal or investment advice",
    stand: (z) => `${z.fakten} facts · ${z.geprueft} checked against the original, ${z.zuPruefen} under review${z.abgelaufen ? `, ${z.abgelaufen} expired` : ""} · last retrieval ${datumDe(z.letzterAbruf)}`,
    exportTitel: "Export",
    exportText: "The register is available as CSV and JSON under the CC BY 4.0 licence (attribution: “ÖkoInvest GmbH – Faktenregister”). Each row names its primary source – whose own terms continue to apply.",
    csv: "Download CSV",
    json: "Download JSON",
    fuss: "Quality levels: class A = law, funding, levies and deadlines; class B = market and statistical values with an external source; class C = our own estimates from project practice (orientation, not measurements). “Checked against the original” means the value was verified at the linked primary source; the second specialist review is still pending. Drafts are not shown. The linked source in its current version is always authoritative.",
    enHinweis: "The facts themselves are kept in German (identifiers, values and source titles) so that citations match the German primary sources.",
  },
};

export default async function QuellenSeite({ params }) {
  await seitenLand(params);
  const sprache = spracheDerAnfrage();
  const t = TEXTE[sprache] || TEXTE.de;
  const heute = new Date();
